// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 프로필 수정 (18번)" (ffc16dac3577418ea10d8d34dd960a15).
// REQ-MYPAGE-002: 닉네임(중복 확인)·소개글·경력(연차·기술 스택) 수정 (#30)
import { useEffect, useState, type FormEvent, type KeyboardEvent, type ReactNode } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorCode, getErrorMessage, getFieldErrors } from "../api/client";
import { checkAvailable } from "../api/member";
import { getMyInfo, updateProfile, type MyInfo, type ProfileUpdateRequest } from "../api/mypage";
import { formatCareer } from "../components/ProfileDetails";
import { useAuth } from "../hooks/useAuth";
import "./ProfileEdit.css";

// Page-local styles from the Stitch <head>; mounted only while this page is shown.
const css =
  ".neo-border {\n      border: 2px solid #111827;\n    }\n    .neo-input {\n      border: 2px solid #111827;\n      border-radius: 4px;\n      transition: all 0.15s ease-in-out;\n    }\n    .neo-input:focus {\n      outline: none;\n      box-shadow: 2px 2px 0px #111827;\n      border-color: #111827;\n    }\n    .neo-btn {\n      border: 2px solid #111827;\n      box-shadow: 2px 2px 0px #111827;\n      transition: transform 0.1s ease, box-shadow 0.1s ease;\n    }\n    .neo-btn:active {\n      transform: translate(2px, 2px);\n      box-shadow: 0px 0px 0px #111827;\n    }";

// 서버와 같은 입력값 규칙 (docs/api.md 입력값 규칙)
const NICKNAME_PATTERN = /^[가-힣A-Za-z0-9]{2,10}$/;
const BIO_MAX_LENGTH = 200;
const CAREER_YEARS_MAX = 50;
const TECH_STACK_MAX = 5;

type Field = "nickname" | "bio" | "careerYears" | "techStacks";
type Errors = Partial<Record<Field | "form", string>>;

// 연차 선택지: 선택 안 함(null), 신입(0), 1~50년차
const CAREER_OPTIONS = Array.from({ length: CAREER_YEARS_MAX + 1 }, (_, years) => years);

interface FormValues {
  nickname: string;
  bio: string;
  careerYears: number | null;
  techStacks: string[];
}

// 중복 확인 결과. value가 지금 입력값과 다르면(확인 후 수정) 다시 확인해야 한다.
interface NicknameCheck {
  value: string;
  available: boolean;
}

function toFormValues(me: MyInfo): FormValues {
  return { nickname: me.nickname, bio: me.bio ?? "", careerYears: me.careerYears, techStacks: me.techStacks };
}

// 처음 값과 달라진 필드만 보낸다 (docs/api.md "보낸 필드만 바꾼다").
function toRequest(initial: FormValues, values: FormValues): ProfileUpdateRequest {
  const request: ProfileUpdateRequest = {};
  if (values.nickname !== initial.nickname) request.nickname = values.nickname;
  if (values.bio !== initial.bio) request.bio = values.bio === "" ? null : values.bio;
  if (values.careerYears !== initial.careerYears) request.careerYears = values.careerYears;
  if (values.techStacks.join() !== initial.techStacks.join()) request.techStacks = values.techStacks;
  return request;
}

function Hint({ tone, children }: { tone: "info" | "ok" | "error"; children?: ReactNode }) {
  if (!children) return null;
  const style = {
    info: "text-gray-500",
    ok: "text-emerald-600",
    error: "text-rose-600",
  }[tone];
  return (
    <p
      className={`text-xs font-semibold mt-1.5 flex items-center gap-1 ${style}`}
      role={tone === "error" ? "alert" : undefined}
    >
      <span aria-hidden="true">{tone === "ok" ? "✓" : tone === "error" ? "⚠" : "ⓘ"}</span>
      {children}
    </p>
  );
}

// 저장 완료 알림 (REQ-MYPAGE-002 "저장 시 수정 완료 알림"). 확인을 누르면 마이페이지로 간다.
function CompleteDialog({ onConfirm }: { onConfirm: () => void }) {
  useEffect(() => {
    const onKeyDown = (e: globalThis.KeyboardEvent) => {
      if (e.key === "Escape") onConfirm();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [onConfirm]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 backdrop-blur-[8px]"
      style={{ backgroundColor: "rgba(255, 253, 245, 0.55)" }}
    >
      <section
        aria-labelledby="profile-edit-complete-title"
        aria-modal="true"
        className="w-full max-w-sm bg-white p-8 text-center border-[2.5px] border-black rounded-2xl shadow-[6px_6px_0_#111111]"
        role="dialog"
      >
        <div className="w-14 h-14 rounded-full bg-emerald-100 text-emerald-600 border-[2.5px] border-black mx-auto mb-5 flex items-center justify-center">
          <svg className="w-8 h-8" fill="none" stroke="currentColor" strokeWidth={3} viewBox="0 0 24 24">
            <path d="M5 13l4 4L19 7" strokeLinecap="round" strokeLinejoin="round"></path>
          </svg>
        </div>
        <h2 className="text-xl font-black mb-2" id="profile-edit-complete-title">
          프로필이 수정되었습니다
        </h2>
        <p className="text-sm text-gray-600 font-medium mb-6">마이페이지에서 바뀐 프로필을 확인하세요.</p>
        <button
          autoFocus
          className="neo-btn w-full py-2.5 bg-[#FFD43B] font-extrabold text-sm rounded cursor-pointer hover:bg-yellow-400"
          onClick={onConfirm}
          type="button"
        >
          마이페이지로 이동
        </button>
      </section>
    </div>
  );
}

export default function ProfileEdit() {
  const navigate = useNavigate();
  const { user, initializing, refreshUser } = useAuth();
  const [initial, setInitial] = useState<FormValues | null>(null);
  const [values, setValues] = useState<FormValues | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [techInput, setTechInput] = useState("");
  const [nicknameCheck, setNicknameCheck] = useState<NicknameCheck | null>(null);
  const [checking, setChecking] = useState(false);
  const [errors, setErrors] = useState<Errors>({});
  const [submitting, setSubmitting] = useState(false);
  const [completed, setCompleted] = useState(false);

  // 로그인이 필요한 화면이다. 새로고침 직후에는 reissue로 로그인 상태를 복구할 때까지 기다린다.
  useEffect(() => {
    if (!initializing && !user) {
      navigate("/login", { replace: true });
    }
  }, [initializing, user, navigate]);

  // 저장 후 refreshUser로 user가 바뀌어도 폼을 다시 불러오지 않도록 memberId에만 반응한다.
  const memberId = user?.memberId;
  useEffect(() => {
    if (memberId === undefined) return;
    let cancelled = false;
    getMyInfo()
      .then((me) => {
        if (cancelled) return;
        setInitial(toFormValues(me));
        setValues(toFormValues(me));
      })
      .catch((error) => {
        if (!cancelled) setLoadError(getErrorMessage(error, "프로필을 불러오지 못했습니다."));
      });
    return () => {
      cancelled = true;
    };
  }, [memberId]);

  const update = <K extends keyof FormValues>(field: K, value: FormValues[K]) => {
    setValues((prev) => (prev ? { ...prev, [field]: value } : prev));
    setErrors((prev) => ({ ...prev, [field]: undefined, form: undefined }));
  };

  const nicknameChanged = Boolean(values && initial && values.nickname !== initial.nickname);
  const nicknameChecked = nicknameCheck !== null && values !== null && nicknameCheck.value === values.nickname;

  async function handleCheckNickname() {
    if (!values || checking) return;
    if (!nicknameChanged) {
      setErrors((prev) => ({ ...prev, nickname: undefined }));
      setNicknameCheck({ value: values.nickname, available: true });
      return;
    }
    if (!NICKNAME_PATTERN.test(values.nickname)) {
      setErrors((prev) => ({ ...prev, nickname: "2~10자, 한글·영문·숫자만 사용할 수 있어요 (공백·특수기호 불가)" }));
      return;
    }
    setChecking(true);
    try {
      const available = await checkAvailable("nickname", values.nickname);
      setNicknameCheck({ value: values.nickname, available });
      setErrors((prev) => ({ ...prev, nickname: available ? undefined : "이미 사용 중인 닉네임이에요." }));
    } catch (error) {
      setErrors((prev) => ({ ...prev, nickname: getErrorMessage(error) }));
    } finally {
      setChecking(false);
    }
  }

  function addTechStack() {
    if (!values) return;
    const name = techInput.trim().toLowerCase();
    if (name === "") return;
    if (values.techStacks.includes(name)) {
      setTechInput("");
      return;
    }
    if (values.techStacks.length >= TECH_STACK_MAX) {
      setErrors((prev) => ({ ...prev, techStacks: `기술 스택은 최대 ${TECH_STACK_MAX}개까지 선택할 수 있어요.` }));
      return;
    }
    update("techStacks", [...values.techStacks, name]);
    setTechInput("");
  }

  function handleTechKeyDown(e: KeyboardEvent<HTMLInputElement>) {
    // 한글 조합 중 Enter는 무시한다 (조합 완료 Enter가 한 번 더 들어온다).
    if (e.key === "Enter" && !e.nativeEvent.isComposing) {
      e.preventDefault();
      addTechStack();
    }
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (!values || !initial || submitting) return;

    const found: Errors = {};
    if (nicknameChanged) {
      if (!NICKNAME_PATTERN.test(values.nickname)) {
        found.nickname = "2~10자, 한글·영문·숫자만 사용할 수 있어요 (공백·특수기호 불가)";
      } else if (!nicknameChecked) {
        found.nickname = "닉네임 중복 확인을 해주세요.";
      } else if (!nicknameCheck?.available) {
        found.nickname = "이미 사용 중인 닉네임이에요.";
      }
    }
    if (values.bio.length > BIO_MAX_LENGTH) {
      found.bio = `소개글은 ${BIO_MAX_LENGTH}자 이하로 입력해주세요.`;
    }
    const request = toRequest(initial, values);
    if (Object.keys(found).length === 0 && Object.keys(request).length === 0) {
      found.form = "변경한 내용이 없어요.";
    }
    setErrors(found);
    if (Object.keys(found).length > 0) return;

    setSubmitting(true);
    try {
      await updateProfile(request);
      // 헤더 등에 보이는 로그인 닉네임도 바꾼다.
      if (request.nickname !== undefined) await refreshUser().catch(() => {});
      setInitial(values);
      setCompleted(true);
    } catch (error) {
      const code = getErrorCode(error);
      if (code === "DUPLICATE_NICKNAME") {
        setNicknameCheck({ value: values.nickname, available: false });
        setErrors({ nickname: "이미 사용 중인 닉네임이에요." });
      } else if (code === "INVALID_INPUT") {
        const next: Errors = {};
        getFieldErrors(error).forEach(({ field, reason }) => {
          next[
            (["nickname", "bio", "careerYears", "techStacks"] as string[]).includes(field) ? (field as Field) : "form"
          ] = reason;
        });
        setErrors(Object.keys(next).length > 0 ? next : { form: getErrorMessage(error) });
      } else {
        setErrors({ form: getErrorMessage(error) });
      }
    } finally {
      setSubmitting(false);
    }
  }

  let nicknameHint: ReactNode = null;
  if (errors.nickname) nicknameHint = <Hint tone="error">{errors.nickname}</Hint>;
  else if (nicknameChanged && nicknameChecked && nicknameCheck?.available)
    nicknameHint = <Hint tone="ok">사용할 수 있는 닉네임이에요.</Hint>;
  else if (nicknameChanged) nicknameHint = <Hint tone="info">닉네임을 바꾸면 중복 확인이 필요해요.</Hint>;

  return (
    <div id="page-profile-edit">
      <style>{css}</style>
      <div
        className="min-h-screen text-gray-900 sm:px-6 lg:px-8 font-sans antialiased pb-8"
        style={{
          backgroundColor: "rgb(255, 253, 245)",
          backgroundImage: "radial-gradient(rgb(217, 212, 195) 1px, transparent 1px)",
          backgroundSize: "18px 18px",
        }}
      >
        {/* BEGIN: MainContainer */}
        <header className="w-full bg-white border-b-[2.5px] border-[#111111] px-6 py-3 flex items-center justify-between mb-8">
          <div className="flex items-center gap-6">
            <a
              href="#"
              className="flex items-center font-sans font-black text-2xl tracking-tight text-[#111111] select-none no-underline"
            >
              {" Dev"}
              <span className="bg-[#FFD43B] border-2 border-black px-1.5 py-0.5 rounded text-black font-mono font-bold text-sm ml-1">
                in_
              </span>
            </a>

            <div className="hidden sm:block w-72 md:w-80">
              <input
                type="text"
                placeholder="검색어를 입력하세요"
                className="w-full px-3 py-1.5 text-sm bg-white border-[2.5px] border-[#111111] rounded-[8px] focus:outline-none placeholder-gray-400 font-medium"
              />
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button
              type="button"
              className="bg-[#2563EB] text-white font-bold border-2 border-black rounded-[8px] shadow-[2px_2px_0_#111111] px-3.5 py-1.5 text-sm hover:opacity-90 transition-opacity"
            >
              {" 질문하기 "}
            </button>{" "}
            <button
              type="button"
              className="bg-white text-gray-900 font-bold border-2 border-black rounded-[8px] shadow-[2px_2px_0_#111111] px-3 py-1.5 text-sm flex items-center hover:bg-gray-50"
            >
              {" 알림"}
              <span className="bg-red-600 text-white rounded-full text-xs px-1.5 py-0.2 font-bold ml-1 leading-none inline-flex items-center justify-center">
                3
              </span>
            </button>{" "}
            <button
              type="button"
              className="bg-[#FFD43B] text-gray-900 font-bold border-2 border-black rounded-[8px] shadow-[2px_2px_0_#111111] px-3.5 py-1.5 text-sm flex items-center gap-1 hover:bg-[#fed33a]"
            >
              <span>{user?.nickname ?? "닉네임"}</span> <span className="text-xs">▾</span>
            </button>
          </div>
        </header>
        <main className="max-w-4xl mx-auto space-y-6 px-4" data-purpose="profile-edit-container">
          {/* BEGIN: HeaderSection */}
          <header className="flex items-center justify-between pb-2" data-purpose="page-header">
            <h1 className="text-2xl sm:text-3xl font-extrabold tracking-tight text-gray-900">프로필 수정</h1>
            <Link
              className="bg-white hover:bg-gray-50 text-gray-900 text-sm font-bold px-4 py-2 rounded-[8px] border-[2.5px] border-[#111111] shadow-[2px_2px_0px_#111111] flex items-center space-x-1 transition-all"
              data-purpose="return-mypage-btn"
              to="/mypage"
            >
              <span>← 마이페이지</span>
            </Link>
          </header>
          {/* END: HeaderSection */}

          {loadError && (
            <div className="bg-rose-50 neo-border rounded-2xl p-4 text-sm font-bold text-rose-700" role="alert">
              {loadError}
            </div>
          )}
          {!values && !loadError && <p className="text-sm font-semibold text-gray-500">프로필을 불러오는 중이에요…</p>}

          {values && (
            <form className="space-y-6" id="profile-edit-form" noValidate onSubmit={handleSubmit}>
              {/* BEGIN: BasicInfoCard (상단 기본 정보) */}
              <section
                className="bg-white neo-border rounded-2xl p-6 sm:p-8 shadow-sm space-y-6"
                data-purpose="basic-info-section"
              >
                {/* Nickname Row */}
                <div className="grid grid-cols-1 sm:grid-cols-12 gap-3 sm:gap-4 items-start">
                  <label className="sm:col-span-2 text-base font-bold text-gray-800 sm:pt-2" htmlFor="nickname">
                    닉네임
                  </label>
                  <div className="sm:col-span-10">
                    <div className="flex flex-col sm:flex-row gap-3">
                      <input
                        aria-invalid={Boolean(errors.nickname)}
                        className="neo-input flex-1 px-3 py-2 text-sm sm:text-base bg-white"
                        id="nickname"
                        maxLength={10}
                        name="nickname"
                        onChange={(e) => update("nickname", e.target.value)}
                        placeholder="닉네임을 입력하세요"
                        type="text"
                        value={values.nickname}
                      />
                      <button
                        className="neo-btn bg-gray-100 hover:bg-gray-200 text-gray-800 font-semibold text-sm px-4 py-2 rounded shrink-0 disabled:opacity-60"
                        data-purpose="check-duplicate-btn"
                        disabled={checking}
                        onClick={handleCheckNickname}
                        type="button"
                      >
                        {checking ? "확인 중…" : "중복 확인"}
                      </button>
                    </div>
                    {nicknameHint}
                  </div>
                </div>

                {/* Bio (소개글) Row */}
                <div className="grid grid-cols-1 sm:grid-cols-12 gap-3 sm:gap-4 items-start">
                  <label className="sm:col-span-2 text-base font-bold text-gray-800 pt-2" htmlFor="bio">
                    소개글
                  </label>
                  <div className="sm:col-span-10 space-y-2">
                    <div className="relative">
                      <textarea
                        aria-invalid={Boolean(errors.bio)}
                        className="neo-input w-full p-3 pb-7 text-sm sm:text-base resize-none bg-white block"
                        id="bio"
                        maxLength={BIO_MAX_LENGTH}
                        name="bio"
                        onChange={(e) => update("bio", e.target.value)}
                        placeholder="자신을 자유롭게 소개해 주세요."
                        rows={4}
                        value={values.bio}
                      />
                      {/* 글자 수 표시 (REQ-MYPAGE-002) */}
                      <span
                        className={`absolute bottom-2.5 right-3 text-xs font-medium select-none pointer-events-none ${
                          values.bio.length >= BIO_MAX_LENGTH ? "text-rose-600" : "text-gray-500"
                        }`}
                        id="char-counter"
                      >
                        {values.bio.length} / {BIO_MAX_LENGTH}
                      </span>
                    </div>
                    {errors.bio ? (
                      <Hint tone="error">{errors.bio}</Hint>
                    ) : (
                      <Hint tone="info">비워 두고 저장하면 소개글이 지워져요.</Hint>
                    )}
                  </div>
                </div>
              </section>
              {/* END: BasicInfoCard */} {/* BEGIN: DetailsGrid (하단 2열 카드 영역) */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6" data-purpose="details-grid">
                {/* BEGIN: CareerCard (좌측 하단 경력 카드) */}
                <section
                  className="bg-white neo-border rounded-2xl p-6 flex flex-col justify-between shadow-sm space-y-6"
                  data-purpose="career-section"
                >
                  <div className="space-y-6">
                    <h2 className="text-lg font-bold text-gray-900 border-b border-gray-200 pb-2">경력</h2>

                    {/* Experience Years Dropdown: 선택 안 함(null), 신입(0), 1~50년차 */}
                    <div className="flex items-center justify-between sm:justify-start gap-4">
                      <label className="text-sm sm:text-base font-bold text-gray-800 w-16" htmlFor="experience-years">
                        연차
                      </label>
                      <div className="relative w-36">
                        <select
                          className="neo-input w-full appearance-none bg-white py-2 pl-3 pr-8 text-sm font-semibold cursor-pointer"
                          id="experience-years"
                          name="experience_years"
                          onChange={(e) => update("careerYears", e.target.value === "" ? null : Number(e.target.value))}
                          value={values.careerYears ?? ""}
                        >
                          <option value="">선택 안 함</option>
                          {CAREER_OPTIONS.map((years) => (
                            <option key={years} value={years}>
                              {formatCareer(years)}
                            </option>
                          ))}
                        </select>
                        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-800">
                          <span className="text-xs font-bold">▼</span>
                        </div>
                      </div>
                    </div>
                    <Hint tone="error">{errors.careerYears}</Hint>

                    {/* Tech Stack Selection Area */}
                    <div className="space-y-3">
                      <label className="block text-sm sm:text-base font-bold text-gray-800" htmlFor="tech-stack-input">
                        기술 스택{" "}
                        <span className="text-xs font-semibold text-gray-500">
                          ({values.techStacks.length} / {TECH_STACK_MAX})
                        </span>
                      </label>
                      <div
                        className="flex flex-wrap gap-2 min-h-[30px]"
                        data-purpose="tech-badges"
                        id="tech-stack-badges"
                      >
                        {values.techStacks.length === 0 && (
                          <span className="text-xs font-medium text-gray-400 py-1">등록한 기술 스택이 없어요</span>
                        )}
                        {values.techStacks.map((name) => (
                          <span
                            className="neo-border bg-white text-gray-800 text-xs sm:text-sm font-medium px-3 py-1 rounded-full flex items-center space-x-1 shadow-sm"
                            key={name}
                          >
                            <span>{name}</span>
                            <button
                              aria-label={`${name} 제거`}
                              className="ml-1 text-gray-500 hover:text-black font-bold focus:outline-none"
                              onClick={() =>
                                update(
                                  "techStacks",
                                  values.techStacks.filter((t) => t !== name),
                                )
                              }
                              type="button"
                            >
                              ×
                            </button>
                          </span>
                        ))}
                      </div>
                      {/* 태그 목록 API(#60)가 생기기 전까지는 이름을 직접 입력한다. 목록에 없는 이름은 서버가 거절한다. */}
                      <div className="flex gap-2">
                        <input
                          className="neo-input flex-1 px-3 py-2 text-sm bg-white placeholder-gray-400"
                          id="tech-stack-input"
                          onChange={(e) => setTechInput(e.target.value)}
                          onKeyDown={handleTechKeyDown}
                          placeholder="예: java, react 입력 후 Enter"
                          type="text"
                          value={techInput}
                        />
                        <button
                          className="neo-btn bg-gray-100 hover:bg-gray-200 text-gray-800 font-semibold text-sm px-3 py-2 rounded shrink-0"
                          data-purpose="add-tech-btn"
                          onClick={addTechStack}
                          type="button"
                        >
                          추가
                        </button>
                      </div>
                      <Hint tone="error">{errors.techStacks}</Hint>
                    </div>
                  </div>

                  {/* Card Footer Hint */}
                  <div className="pt-4 border-t border-gray-100">
                    <p className="text-xs text-gray-500 font-medium">※ 등록한 경력은 질문/답변 옆에 함께 표시돼요</p>
                  </div>
                </section>
                {/* END: CareerCard */} {/* BEGIN: InterestsCard (우측 하단 관심 카테고리 카드) */}
                {/* 관심 카테고리·알림 설정은 카테고리 목록 API가 생기면 #69에서 연결한다 */}
                <section
                  className="bg-white neo-border rounded-2xl p-6 flex flex-col justify-between shadow-sm space-y-6 opacity-70"
                  data-purpose="interests-section"
                >
                  <div className="space-y-4">
                    <div>
                      <h2 className="text-lg font-bold text-gray-900">관심 카테고리</h2>
                      <p className="text-xs text-gray-500 mt-0.5">관심 카테고리에 새 질문이 올라오면 알림을 받아요.</p>
                    </div>
                    <div className="rounded-xl border-2 border-dashed border-gray-300 bg-gray-50 p-4 text-center text-sm font-bold text-gray-500">
                      준비 중이에요
                    </div>
                  </div>
                  <div
                    className="pt-4 border-t border-gray-100 flex items-center justify-end space-x-3"
                    data-purpose="notification-toggle-wrapper"
                  >
                    <span className="text-sm font-bold text-gray-400">새 질문 알림</span>
                    <label className="relative inline-flex items-center cursor-not-allowed">
                      <input disabled className="sr-only peer" id="notification-toggle" type="checkbox" />
                      <div className="w-12 h-6 bg-gray-200 neo-border rounded-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-2 after:border-gray-900 after:rounded-full after:h-5 after:w-5"></div>
                    </label>
                  </div>
                </section>
                {/* END: InterestsCard */}
              </div>
              {/* END: DetailsGrid */}
              <Hint tone="error">{errors.form}</Hint>
              {/* BEGIN: ActionButtons (최하단 저장/취소 버튼) */}
              <div className="flex items-center justify-end space-x-4 pt-4" data-purpose="form-actions">
                <button
                  className="neo-btn bg-white hover:bg-gray-100 text-gray-900 font-bold px-8 py-2.5 rounded text-sm sm:text-base min-w-[100px]"
                  data-purpose="cancel-btn"
                  onClick={() => navigate("/mypage")}
                  type="button"
                >
                  취소
                </button>
                <button
                  className="neo-btn bg-slate-300 hover:bg-slate-400 text-gray-900 font-bold px-8 py-2.5 rounded text-sm sm:text-base min-w-[100px] disabled:opacity-60 disabled:cursor-wait"
                  data-purpose="save-btn"
                  disabled={submitting}
                  type="submit"
                >
                  {submitting ? "저장 중…" : "저장"}
                </button>
              </div>
              {/* END: ActionButtons */}
            </form>
          )}
          {/* END: ProfileEditForm */}
        </main>
        {/* END: MainContainer */}
      </div>
      {completed && <CompleteDialog onConfirm={() => navigate("/mypage")} />}
    </div>
  );
}
